// Example: graceful shutdown with 5s drain
ctx := context.Background()
stream, err := client.StartStream(ctx, req)
if err != nil { return err }
// in another goroutine we read: for { msg, err := stream.Recv() if err == ErrStreamClosed { break } if err != nil { return err } handle(msg) }
// When shutting down: ctxShutdown, cancel := context.WithTimeout(context.Background(), 7*time.Second) defer cancel()
err = stream.GracefulClose(ctxShutdown, 5*time.Second)
if err != nil { // fallback to immediate close to avoid blocking
 stream.CloseImmediate(fmt.Errorf("shutdown: %v", err)) }

// Example: per-read deadline override
stream.WithReadDeadline(150 * time.Millisecond)
msg, err := stream.Recv()
if errors.Is(err, ErrDeadline) { // retry logic or continue }
